           // Load identity sled from ~/.identity/<account_id>/sled.json
           // Validate against session_id and WireGuard/SSH certificate
           // Zero‑trust: validate all session IDs against sled before allowing access
       }
   }
   ```

2. **crates/op-grpc-bridge/src/grpc_server.rs**
   ```rust
