   async fn call(
       &self,
       request: Request<crate::proto::DbusCallRequest>,
   ) -> Result<Response<crate::proto::DbusCallResponse>, Status> {
       let req = request.into_inner();

       // 1. Parse and validate D‑Bus path (same for session/system bus)
       let (plugin_id, path_segments) = parse_and_validate_dbus_path(
           &req.destination, &req.path, &req.interface, &req.method
       )?;

       // 2. Validate destination legality against plugin schema SSOT
       if let Err(e) = validate_dbus_destination(&req.destination, &plugin_id, Some(&req.method)) {
           return Err(Status::invalid_argument(format!(_("destination validation failed: {}", e)));
       }

       // 3. Handle session bus with identity validation
       let actor_id = if req.bus == "session" {
           // Validate session identity using persisted identity sled
           SessionValidator::validate_session_identity(&req.identity).await
               .map_err(|e| Status::unauthorized(format!("session validation failed: {}", e)))?;
           req.identity.clone() // Session ID becomes actor_id
       } else {
           "op-grpc-bridge".to_string() // Default actor for system bus
       };

       // 4. Route writes through MutationEngine (single write door)
       let result = self
           .mutation_engine
