               plugin_id.clone(),
               req.destination,
               req.path,
               req.interface,
               req.method,
               req.json_body,
               Some(actor_id), // Pass actor_id to MutationEngine
           )
           .await
           .map_err(|e| Status::internal(format!("MutationEngine D‑Bus call failed: {}", e)))?;

       Ok(Response::new(crate::proto::DbusCallResponse {
           success: true,
           json_result: result,
           error: String::new(),
       }))
