       pub async fn validate_session_identity(&self, session_id: &str) -> anyhow::Result<()> {
           // Read canonical sled from existing /dev/shm/plugin_schema.dat
           let mut file = std::fs::File::open(&self.sled_path)
               .map_err(|e| anyhow::anyhow!("failed to open identity sled at {}: {}", self.sled_path, e))?;

