//! The Identity Sled & Shuttle Bridge
//!
//! THE SLED: a `#[repr(C)]` struct written into `/dev/shm/plugin_schema.dat`
//! by the SchemaEngine whenever the active PluginSchema mutates.
//!
//! THE SHUTTLE: reads that mapping via zero-copy mmap, extracts the
//! Strike/Etch (hashed footprint + WireGuard identity), stamps
//! `GB_FOOTPRINT` / `GB_TRACE_ID` into the process environment, then
//! writes a stateless Xray config into `/dev/shm/xray-ghostbridge.json`
//! and spawns Xray — all without touching any Btrfs-backed path.

use memmap2::MmapOptions;
use serde::{Deserialize, Serialize};
use std::collections::HashSet;
use std::env;
use std::fs::{self, File};
use std::io::Write;
use std::process::Command;
use std::sync::atomic::{AtomicU64, Ordering};

pub const SHM_SLED_PATH: &str = "/dev/shm/plugin_schema.dat";
pub const SHM_XRAY_CONFIG: &str = "/dev/shm/xray-ghostbridge.json";

/// Resolve the tonic-web gRPC bridge (op-grpc-bridge-zeroclaw) endpoint that
/// xray redirects every Unix-backed route — and the catch-all fallback — to.
/// The bridge uses gRPC reflection to demux by service/method and dials backend
/// unix sockets natively; xray never dials sockets directly, it just does
/// TLS + SNI routing to this one address.
///
/// Single source of truth, no port literal baked in here. In priority order:
///   1. the Gemma route for the createunixsocket gateway (tag `unix-socket`,
///      else `zeroclaw`) — registry-derived, the exact value the bridge serves;
///   2. the `ZEROCLAW_BIND_ADDR` env the bridge itself binds with (deployment
///      override / boot-before-Gemma).
/// `op-grpc-bridge` owns its own default and cannot be imported here (it depends
/// on this crate), so when neither source is present we fall back to loopback
/// with no port and emit no bridge route (see callers).
fn grpc_bridge_endpoint(routes: &[XrayRoute]) -> Option<(String, u16)> {
    let normalize = |h: &str| {
        if h == "0.0.0.0" || h.is_empty() {
            "127.0.0.1".to_string()
        } else {
            h.to_string()
        }
    };
    // 1. Registry-sourced: the createunixsocket / zeroclaw gateway route.
    for tag in ["unix-socket", "zeroclaw"] {
        if let Some((host, port)) = routes.iter().find_map(|r| match &r.backend {
            GemmaBackend::Grpc { host, port, .. } if r.tag == tag => Some((host.clone(), *port)),
            _ => None,
        }) {
            return Some((normalize(&host), port));
        }
    }
    // 2. The bridge's own bind env (shared deployment config).
    if let Some((host, port)) = env::var("ZEROCLAW_BIND_ADDR")
        .ok()
        .and_then(|addr| {
            addr.rsplit_once(':')
                .map(|(h, p)| (h.to_string(), p.to_string()))
        })
        .and_then(|(h, p)| p.parse::<u16>().ok().map(|port| (h, port)))
    {
        return Some((normalize(&host), port));
    }
    None
}

