  -H "Content-Type: application/json" \
  -d '{"username": "admin", "password": "admin123"}' \
  http://127.0.0.1:8080/system.IdentityService/Login
2. System Metrics (Get Health)

curl -s -X POST \
  -H "Content-Type: application/json" \
